//! What a program gives the starter: its names, its server, and the optional MCP entry; and how a run ends.
//!
//! Pattern: Strategy (the program implements [`Program`]; later generated by fs-blueprint from the build plan, ADR 0099)
//! + Value objects ([`Exit`], [`Failure`]).

use std::ffi::OsString;

use fs_types::coded::Code;

use crate::names::{ActorName, ContractReq, FrontendId, ProgramName};

/// The exit code of `fs-<program>`. A frontend's own exit code is passed on unchanged.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Exit(u8);

impl Exit {
    /// Done.
    pub const DONE: Self = Self(0);
    /// Failed (visible note given).
    pub const FAILED: Self = Self(1);
    /// Wrong words.
    pub const USAGE: Self = Self(2);
    /// The frontend's answer to `--check`: the server's contract does not fit (ADR 0094 item 4, proposal 3).
    pub const CONTRACT: Self = Self(3);

    /// A frontend's exit code: 0 to 255 as it is, anything else (a signal, out of range) is [`Exit::FAILED`].
    #[must_use]
    pub fn of_frontend(code: i32) -> Self {
        u8::try_from(code).map_or(Self::FAILED, Self)
    }

    /// The number.
    #[must_use]
    pub fn code(self) -> u8 {
        self.0
    }
}

/// A failure of the program's own part (`serve`, MCP entry, a start hook): its exit and its code, unchanged.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Failure {
    /// How `fs-<program>` ends.
    pub exit: Exit,
    /// The program's code (its own prefix, such as `activities-error-`).
    pub code: Code,
}

/// The program, as the starter needs it.
pub trait Program {
    /// `activities`.
    fn name(&self) -> &ProgramName;

    /// The program's version, `major.minor.patch` (usually `env!("CARGO_PKG_VERSION")`).
    fn version(&self) -> &str;

    /// The AppStream id (`net.freesynergy.Activities`): what a frontend manifest names in `<extends>` and `<requires>`.
    fn app_id(&self) -> &str;

    /// The contract the program's server offers (`history 0.1`): what `fs:requires` of a frontend is checked against.
    fn contract(&self) -> &ContractReq;

    /// The frontend that comes with the program and opens by default (ADR 0074 §8). A default only (O11): the person can switch
    /// to another in the display menu (kept by [`Preference`]), and that choice wins over this one.
    fn standard_frontend(&self) -> &FrontendId;

    /// Runs the server with its own words (`fs-<program> serve ...`); returns when it ends. Review condition S2: the starter
    /// starts it detached through fs-rpc `CommandStarter` (`<own exe> serve --socket S`); `ProgramRoot` comes later.
    ///
    /// # Errors
    /// The program's failure, with its exit (2 for its wrong words, 1 otherwise).
    fn serve(&self, words: &[OsString]) -> Result<(), Failure>;
}

/// The MCP entry of a program build (fs-mcp-gate, later; review condition S3). It decides whether MCP is switched on, which
/// tools the actor may use, and marks every call as the actor's (never the person's). The starter only hands over the actor.
pub trait McpEntry {
    /// Serves MCP over stdio for `actor`; returns when the client ends.
    ///
    /// # Errors
    /// The entry's failure (switched off, actor not allowed, ...), with its own code.
    fn serve_mcp(&self, actor: &ActorName) -> Result<(), Failure>;
}

/// The person's choice of frontend for a program (ADR 0094 item 4 b: word > choice of the person > standard). Where it is
/// kept is the program's (its settings); the starter only asks.
pub trait Preference {
    /// The chosen frontend, if the person chose one.
    fn frontend(&self, program: &ProgramName) -> Option<FrontendId>;
}

/// No choice kept: the standard frontend opens unless a word names another.
#[derive(Clone, Copy, Debug, Default)]
pub struct NoPreference;

impl Preference for NoPreference {
    fn frontend(&self, _: &ProgramName) -> Option<FrontendId> {
        None
    }
}
